import {crc32} from './legacy-protocol.js';
import {encodeGroup,recoverGroup,repairsFor} from './fec.js';
export const GRID=16,RATE=12,COUNTDOWN=3,VERSION='2.0.0';
export function crc16(bytes){let c=0xffff;for(const b of bytes){c^=b<<8;for(let j=0;j<8;j++)c=(c&0x8000)?(c<<1)^0x1021:c<<1;c&=65535;}return c;}
function bitsOf(fields){const bits=[];for(const [n,width]of fields)for(let i=width-1;i>=0;i--)bits.push((n>>>i)&1);return bits;}
function bytesOf(bits){const bytes=new Uint8Array(Math.ceil(bits.length/8));bits.forEach((b,i)=>bytes[i>>3]|=b<<(7-i%8));return bytes;}
export function makeRecord(tag,group,k,slot,data){const bits=bitsOf([[1,2],[tag,14],[group,24],[k,6],[slot,6],...[...data].map(b=>[b,8])]);return Uint8Array.from([...bits,...bitsOf([[crc16(bytesOf(bits)),16]])]);}
export function readRecord(bits){if(bits.length!==124)return null;const body=bits.slice(0,108);let pos=0;const take=n=>{let v=0;while(n--)v=v*2+bits[pos++];return v;};const type=take(2),tag=take(14),group=take(24),k=take(6),slot=take(6),data=Uint8Array.from({length:7},()=>take(8)),check=take(16);if(type!==1||k<1||k>32||slot>=k+repairsFor(k)||crc16(bytesOf(body))!==check)return null;return {tag,group,k,slot,data};}
export function cellsFor(record){const cells=new Uint8Array(128);cells.set(record,2);cells[0]=cells[127]=1;let a=0,b=0;record.forEach((v,i)=>i%2?b^=v:a^=v);cells[1]=a;cells[126]=b;return cells;}
export function recordFromCells(cells){if(!cells||cells.length!==128||!cells[0]||!cells[127])return null;let a=0,b=0;for(let i=0;i<124;i++)i%2?b^=cells[i+2]:a^=cells[i+2];if(a!==cells[1]||b!==cells[126])return null;return readRecord(cells.slice(2,126));}
function packetize(envelope,tag){const records=[],groups=Math.ceil(envelope.length/224);for(let g=0;g<groups;g++){const slice=envelope.subarray(g*224,(g+1)*224),k=Math.ceil(slice.length/7),source=[];for(let i=0;i<k;i++){const bytes=new Uint8Array(7);bytes.set(slice.subarray(i*7,i*7+7));source.push(bytes);}encodeGroup(source).forEach((data,slot)=>records.push(makeRecord(tag,g,k,slot,data)));}return records;}
function envelope(raw,payload,compressed){const a=new Uint8Array(13+payload.length),v=new DataView(a.buffer);a[0]=compressed?1:0;v.setUint32(1,payload.length);v.setUint32(5,raw.length);v.setUint32(9,crc32(raw));a.set(payload,13);return a;}
export async function prepare(text,{tag=crypto.getRandomValues(new Uint16Array(1))[0]&16383}={}){const raw=new TextEncoder().encode(text);if(!raw.length)throw Error('Enter a message first.');if(raw.length>0xffffffff-13)throw Error('Document exceeds the wire format capacity.');let chosen=envelope(raw,raw,false),records=packetize(chosen,tag),compressed=false;
 if(typeof CompressionStream!=='undefined'){const zipped=new Uint8Array(await new Response(new Blob([raw]).stream().pipeThrough(new CompressionStream('gzip'))).arrayBuffer());const candidate=envelope(raw,zipped,true),test=packetize(candidate,tag);if(test.length<records.length){chosen=candidate;records=test;compressed=true;}}
 // Short groups carry extra distinct repair units for a 0.75s capture window.
 // No message or pattern loop is needed.
 const displays=records.length;return{records,displays,seconds:displays/RATE,bytes:raw.length,encodedBytes:chosen.length,compressed,tag};}
export class Receiver{
 constructor(){this.transfers=new Map();this.result=null;this.revision=0;this.lastAttempt=-1;}
 add(record){if(!record)return;const{tag,group,k,slot,data}=record;if(!this.transfers.has(tag)){if(this.transfers.size>=4)this.transfers.delete(this.transfers.keys().next().value);this.transfers.set(tag,{groups:new Map()});}const t=this.transfers.get(tag);let g=t.groups.get(group);if(!g){g={k,units:new Map(),conflicts:new Set(),decoded:null};t.groups.set(group,g);}if(g.k!==k||g.conflicts.has(slot))return;const previous=g.units.get(slot);if(previous){if(previous.every((b,i)=>b===data[i]))return;g.units.delete(slot);g.conflicts.add(slot);}else g.units.set(slot,data);g.decoded=recoverGroup(k,g.units);this.revision++;}
 get progress(){let best={received:0,total:0};for(const t of this.transfers.values()){const h=t.groups.get(0)?.decoded;if(!h||h.length<2)continue;const first=new Uint8Array(14);first.set(h[0]);first.set(h[1],7);const bytes=13+new DataView(first.buffer).getUint32(1),total=Math.ceil(bytes/7);let received=0;for(const [id,g]of t.groups)if(id<Math.ceil(bytes/224))received+=g.decoded?g.k:g.units.size;if(received>best.received)best={received:Math.min(received,total),total};}return best;}
 async finish(){if(this.result!==null)return this.result;if(this.lastAttempt===this.revision)return null;this.lastAttempt=this.revision;
 for(const t of this.transfers.values()){const h=t.groups.get(0)?.decoded;if(!h||h.length<2)continue;const header=new Uint8Array(14);header.set(h[0]);header.set(h[1],7);const v=new DataView(header.buffer),length=v.getUint32(1),original=v.getUint32(5),check=v.getUint32(9),total=13+length,groups=Math.ceil(total/224);if(header[0]>1||!original||!length||groups>0x1000000)continue;let ready=true;for(let i=0;i<groups;i++){const g=t.groups.get(i);if(!g?.decoded||g.k!==Math.ceil(Math.min(224,total-i*224)/7)){ready=false;break;}}if(!ready)continue;
 const all=new Uint8Array(total);for(let i=0;i<groups;i++)t.groups.get(i).decoded.forEach((b,j)=>all.set(b.subarray(0,Math.min(7,total-i*224-j*7)),i*224+j*7));let raw=all.subarray(13);
 try{if(header[0]===1){const reader=new Blob([raw]).stream().pipeThrough(new DecompressionStream('gzip')).getReader(),chunks=[];let size=0;try{while(true){const r=await reader.read();if(r.done)break;size+=r.value.length;if(size>original)throw Error('Invalid expansion length');chunks.push(r.value);}}catch(e){await reader.cancel().catch(()=>{});throw e;}if(size!==original)continue;raw=new Uint8Array(size);let at=0;for(const c of chunks){raw.set(c,at);at+=c.length;}}
 if(raw.length===original&&crc32(raw)===check){this.result=new TextDecoder('utf-8',{fatal:true}).decode(raw);return this.result;}}catch{} }
 return null;}
}
